design.prefetcher_source:
#include <vector>
#include <algorithm> // For std::erase, std::insert
#include <cstddef>   // For uint8_t etc.
#include "address.h"
#include "modules.h"

// Define the prefetcher struct
struct gen_default_s2 : public champsim::modules::prefetcher {
    using prefetcher::prefetcher;

    // StreamEntry to track state for each potential stream
    struct StreamEntry {
        champsim::block_number last_demand_block;
        champsim::block_number::difference_type current_stride;
        uint8_t confidence; // Number of consecutive times the stride was observed
        bool valid; // Indicates if this entry holds meaningful data

        // Default constructor
        StreamEntry() : last_demand_block{}, current_stride(0), confidence(0), valid(false) {}
        // Constructor for initialization
        StreamEntry(champsim::block_number block, champsim::block_number::difference_type stride, uint8_t conf, bool val)
            : last_demand_block(block), current_stride(stride), confidence(conf), valid(val) {}
    };

    static const uint32_t STREAMS_SIZE = 8; // Number of stream entries in our LRU table
    static const uint8_t CONFIDENCE_THRESHOLD = 2; // How many consistent strides before prefetching

    std::vector<StreamEntry> streams_; // Use std::vector as an LRU list

    // Constructor for the prefetcher
    gen_default_s2() {
        // Initialize all stream entries to an invalid state.
        // Pre-allocate memory and fill with default-constructed StreamEntry objects.
        streams_.reserve(STREAMS_SIZE);
        for (uint32_t i = 0; i < STREAMS_SIZE; ++i) {
            streams_.emplace_back(); // Adds a default-constructed StreamEntry
        }
    }

    // Called on every core-cache access
    uint32_t prefetcher_cache_operate(champsim::address addr, champsim::address ip,
                                       uint8_t cache_hit, bool useful_prefetch,
                                       access_type type, uint32_t metadata_in) {
        // The prefetcher trains only on demand accesses from the core.
        // Ignore prefetches (type == access_type::PREFETCH) and cache hits/useful prefetches for simplicity.
        if (type == access_type::PREFETCH) {
            return metadata_in;
        }

        champsim::block_number current_blk{addr};

        int match_idx = -1;

        // --- Step 1: Search for an exact match on last_demand_block ---
        // This indicates a re-access to the same block, or a potential loop/stall.
        // This type of match has the highest priority.
        for (int i = 0; i < STREAMS_SIZE; ++i) {
            if (streams_[i].valid && streams_[i].last_demand_block == current_blk) {
                match_idx = i;
                break; // Found the highest priority match, stop searching
            }
        }

        // --- Step 2: If no exact match, search for a stride-based continuation match ---
        // This indicates the current access continues a known stride pattern, or starts a new one.
        if (match_idx == -1) {
            for (int i = 0; i < STREAMS_SIZE; ++i) {
                if (streams_[i].valid) {
                    champsim::block_number::difference_type observed_stride = champsim::offset(streams_[i].last_demand_block, current_blk);
                    // A match occurs if:
                    // 1. The access is to a different block (observed_stride != 0).
                    // 2. The entry's current_stride is uninitialized (0), meaning this is the first stride observation.
                    // 3. Or, the observed stride matches the entry's previously recognized stride.
                    if (observed_stride != 0 && (streams_[i].current_stride == 0 || streams_[i].current_stride == observed_stride)) {
                        match_idx = i;
                        break; // Found a stride continuation match, stop searching
                    }
                }
            }
        }

        // --- Step 3: Process the matched entry or allocate a new one ---
        if (match_idx != -1) {
            // A matching stream entry was found. Move it to the MRU position (front) of the vector.
            // This maintains the LRU property: front is MRU, back is LRU.
            StreamEntry matched_entry = streams_[match_idx];
            streams_.erase(streams_.begin() + match_idx);
            streams_.insert(streams_.begin(), matched_entry);

            StreamEntry& active_entry = streams_[0]; // Reference to the now MRU entry
            active_entry.valid = true; // Ensure it's marked as valid

            // Calculate the stride from the *last* block in this stream to the *current* block.
            champsim::block_number::difference_type observed_stride = champsim::offset(active_entry.last_demand_block, current_blk);

            if (observed_stride != 0) { // The current access is to a new block, potential stride
                if (active_entry.current_stride == observed_stride) { // Consistent stride observed
                    active_entry.confidence++; // Increment confidence
                } else { // Stride changed or this is the first non-zero stride for this entry
                    active_entry.current_stride = observed_stride; // Update the stride
                    active_entry.confidence = 1; // Reset confidence as a new pattern potentially starts
                }

                // If confidence is high enough, issue a prefetch for the next block in the predicted stride.
                // Constraint: At most one prefetch per access. This `if` ensures that.
                if (active_entry.confidence >= CONFIDENCE_THRESHOLD) {
                    // The prefetch target is the current block plus the observed stride.
                    prefetch_line(champsim::address{current_blk + active_entry.current_stride}, true, metadata_in);
                }
                active_entry.last_demand_block = current_blk; // Update the last accessed block for this stream
            } else { // observed_stride == 0: current_blk is the same as active_entry.last_demand_block
                // This means the stream has stalled, looped, or the same block was re-accessed.
                // Reset stride and confidence for this entry as the pattern is broken or on hold.
                active_entry.current_stride = 0;
                active_entry.confidence = 0;
                // active_entry.last_demand_block is already `current_blk` due to the match condition.
            }
        } else { // No matching stream entry found, allocate a new one (LRU replacement)
            // Evict the LRU entry (last element in the vector) and insert a new entry at the MRU position (front).
            streams_.pop_back(); // Removes the LRU entry
            // Insert a new entry initialized with the current block, zero stride, zero confidence, and valid.
            streams_.insert(streams_.begin(), {current_blk, 0, 0, true});
        }

        return metadata_in;
    }

    // Called on a fill into the cache being modelled
    uint32_t prefetcher_cache_fill(champsim::address addr, long set, long way,
                                    uint8_t prefetch, champsim::address evicted_addr,
                                    uint32_t metadata_in) {
        // According to the design brief, this prefetcher "trains on demand accesses".
        // No specific action or state update is required upon a cache fill for this design.
        return metadata_in;
    }
};

reference.prefetcher_source:
#include <cstdint>
#include "address.h"
#include "modules.h"

struct gen_fill_only_conservative_s2 : public champsim::modules::prefetcher {
  using prefetcher::prefetcher;

  uint32_t prefetcher_cache_operate(champsim::address addr, champsim::address ip,
                                     uint8_t cache_hit, bool useful_prefetch,
                                     access_type type, uint32_t metadata_in) {
    // This prefetcher never trains on demand misses, so no action here.
    return metadata_in;
  }

  uint32_t prefetcher_cache_fill(champsim::address addr, long set, long way,
                                  uint8_t prefetch, champsim::address evicted_addr,
                                  uint32_t metadata_in) {
    // Convert the filled address to a block number for arithmetic.
    champsim::block_number blk{addr};

    // Calculate the address of the next line.
    champsim::block_number prefetch_blk = blk + 1;

    // Issue a prefetch for the next line, one line ahead.
    this->prefetch_line(champsim::address{prefetch_blk}, true, metadata_in);

    return metadata_in;
  }
};
